#define NEW new

extern "C" int strcmp(const char *, const char *);
extern "C" void debug_print(const char *, ...);

typedef unsigned int nslSourceId;
typedef unsigned int nslSoundId;

enum
{
	NSL_INVALID_ID = 0,
	Tutorial_Step_Num = 21,
	GT_TUTORIAL_PRESS_START = 0,
	GT_TUTORIAL_PAUSE_BUTTONS = 1
};

class stringx
{
	char *chars;
	void *my_buf;
public:
	stringx();
	~stringx();
	const char *c_str() const { return chars; }
};

class EventRecipient
{
public:
	EventRecipient();
	virtual ~EventRecipient();
};

struct TutorialStep
{
	char vo_name_string[100];
};

extern TutorialStep GTutorialStep[];
extern stringx ksGlobalTextArray[];

class os_developer_options
{
public:
	enum
	{
		FLAG_NO_AUDIO
	};
	static os_developer_options *inst();
	bool is_flagged(int) const;
};

extern nslSourceId nslLoadSource(const char *);

struct font_info_t {};

struct frontendmanager_t
{
	font_info_t font_info;
};

extern frontendmanager_t frontendmanager;

namespace Font
{
	enum HORIZJUST
	{
		HORIZJUST_LEFT
	};
	enum VERTJUST
	{
		VERTJUST_CENTER
	};
}

class color32
{
	unsigned int value;
public:
	color32(unsigned char, unsigned char, unsigned char, unsigned char);
};

class BoxText
{
public:
	BoxText(font_info_t *, const stringx &, int, int, int, float,
	        Font::HORIZJUST, Font::VERTJUST, color32, int);
	void makeBox(int, int);
};

class IGOTutorialManager : public EventRecipient
{
	void *buttonTexture[8];
	bool finished;
	bool first_step;
	int current_step;
	float current_step_time;
	int last_step;
	bool air_trick_in_chain;
	bool face_trick_in_chain;
	nslSoundId current_VO;
	int current_trick;
	int current_gap;
	bool needs_to_be_in_tube;
	bool is_perfect;
	bool show_advancement_text;
	bool show_hint_text;
	stringx ins_text;
public:
	IGOTutorialManager();
	void process_help_string(stringx &, const char *);
	stringx help_text;
	stringx button_text;
	BoxText *instruction_text;
};

IGOTutorialManager::IGOTutorialManager()
{
	//  Load all the VO
	if(!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		for (int index = 0; index < Tutorial_Step_Num; index++)
		{
			if (strcmp(GTutorialStep[index].vo_name_string, "TUTORIAL_NONE"))
			{
				nslSourceId s = nslLoadSource(GTutorialStep[index].vo_name_string);
				if (s == NSL_INVALID_ID)
					debug_print("FIXME: MISSING %s SOUND\n", GTutorialStep[index].vo_name_string);
			}
		}

	process_help_string(ins_text, ksGlobalTextArray[GT_TUTORIAL_PRESS_START].c_str());
	instruction_text = NEW BoxText(&frontendmanager.font_info, ins_text, 40, 40, 800, 1.0f, Font::HORIZJUST_LEFT, Font::VERTJUST_CENTER, color32(255, 255, 125, 255), 15);
	instruction_text->makeBox(330,200);

	process_help_string(button_text, ksGlobalTextArray[GT_TUTORIAL_PAUSE_BUTTONS].c_str());

	finished = false;
	first_step = true;
	needs_to_be_in_tube = false;
	current_trick = -1;
	current_gap = -1;
	current_step = 0;
	current_step_time = 0.0f;
	air_trick_in_chain = false;
	face_trick_in_chain = false;
	is_perfect = false;
	show_advancement_text = false;
	show_hint_text = false;
	current_VO = NSL_INVALID_ID;
}
